import{_ as a,C as r,c as s,o as l,ag as t,j as i,G as n}from"./chunks/framework.Bw-5EFTY.js";const b=JSON.parse('{"title":"Voxel Integration with FluentAffiliate","description":"","frontmatter":{},"headers":[],"relativePath":"guide/integrations/voxel-integration-with-fluentaffiliate.md","filePath":"guide/integrations/voxel-integration-with-fluentaffiliate.md","lastUpdated":1755603750000}'),u={name:"guide/integrations/voxel-integration-with-fluentaffiliate.md"};function g(f,e,c,h,d,p){const o=r("ZoomableImage");return l(),s("div",null,[e[0]||(e[0]=t('<h1 id="voxel-integration-with-fluentaffiliate" tabindex="-1">Voxel Integration with FluentAffiliate <a class="header-anchor" href="#voxel-integration-with-fluentaffiliate" aria-label="Permalink to &quot;Voxel Integration with FluentAffiliate&quot;">​</a></h1><p>Voxel is a powerful and versatile theme that enables you to build advanced, dynamic websites and directories directly within WordPress. From multi-vendor directories to booking sites, Voxel can turn post type into a product that can be sold or subscribed to.</p><p>If you use the Voxel theme and want to boost your sales with an affiliate program, you&#39;re in the right place. By connecting Voxel with FluentAffiliate, you can easily track sales, manage affiliate commissions, and grow your business through referral marketing.</p><p>This guide will walk you through the step-by-step process of connecting the Voxel theme with FluentAffiliate.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Voxel is a pro feature of FluentAffiliate. To use it, you need FluentAffiliate Pro.</p><p>To get started, please make sure you have the Voxel theme and the FluentAffiliate plugin installed and activated on your WordPress website.</p></div><h2 id="enable-the-voxel-integration" tabindex="-1">Enable the Voxel Integration <a class="header-anchor" href="#enable-the-voxel-integration" aria-label="Permalink to &quot;Enable the Voxel Integration&quot;">​</a></h2><p>First, you’ll need to enable the integration from your FluentAffiliate dashboard. It only takes a few clicks.</p><ol><li>Go to your <strong>FluentAffiliate Dashboard</strong> from your WordPress admin panel.</li><li>Click on the <strong>Settings</strong> tab in the top navigation bar.</li><li>From the left sidebar, select the <strong>Integration Settings</strong> option.</li><li>Inside the Integration Settings, you will see a list of available integrations. Find <strong>Voxel</strong> in this list and click the toggle button next to it to enable the integration. Once enabled, the toggle will turn blue, and a <strong>Manage</strong> link will appear.</li></ol>',8)),i("p",null,[n(o,{src:"/guide/public/images/integrations/voxel/integration-setup-options.webp",alt:"Integration Settings"})]),e[1]||(e[1]=t('<h2 id="configure-voxel-settings" tabindex="-1">Configure Voxel Settings <a class="header-anchor" href="#configure-voxel-settings" aria-label="Permalink to &quot;Configure Voxel Settings&quot;">​</a></h2><p>After enabling the integration, click on the <strong>Manage</strong> link to configure how commissions are handled for your <strong>Voxel</strong> products. This is where you can set custom commission rates that are different from your default settings.</p><p>A settings panel will appear with the following options:</p><ul><li><strong>Enable Affiliate Integration for Voxel:</strong> This checkbox acts as the master switch for the integration. Ensure it is checked.</li><li><strong>Enable custom rate for specific products:</strong> Check this box if you want to set a specific commission rate for certain Voxel products, overriding the global commission settings.</li></ul>',4)),i("p",null,[n(o,{src:"/guide/public/images/integrations/voxel/voxel-settings-configuration.webp",alt:"Voxel Settings"})]),e[2]||(e[2]=t('<h3 id="custom-affiliate-rate-configuration" tabindex="-1">Custom Affiliate Rate Configuration <a class="header-anchor" href="#custom-affiliate-rate-configuration" aria-label="Permalink to &quot;Custom Affiliate Rate Configuration&quot;">​</a></h3><p>Once you enable custom rates, you can define specific commission rules for individual Voxel products.</p><ol><li><strong>Voxel products:</strong> In the <strong>Select</strong> field, start typing the name of a Voxel product. Choose the product you want to set a custom rate for from the list.</li><li><strong>Select Rate:</strong> Enter the commission value in the box (e.g., enter 15 for a 15% or $15 commission). Then, select the <strong>Rate Type</strong> from the dropdown menu, choosing either a <strong>Percentage (%)</strong> or a <strong>Fixed</strong> amount.</li><li><strong>Add More Rates:</strong> Click the <strong>+Add New Rate</strong> button to add another custom rate for a different product. You can repeat this process to configure as many product-specific rates as you need.</li><li><strong>Save Settings:</strong> Once you’re done, click the <strong>Save Settings</strong> button to apply your changes.</li></ol>',3)),i("p",null,[n(o,{src:"/guide/public/images/integrations/voxel/custom-affiliate-rates.webp",alt:"Voxel Settings"})]),e[3]||(e[3]=t('<h2 id="generate-an-affiliate-link" tabindex="-1">Generate an Affiliate Link <a class="header-anchor" href="#generate-an-affiliate-link" aria-label="Permalink to &quot;Generate an Affiliate Link&quot;">​</a></h2><p>Now that the integration is set up, your affiliates can start promoting your Voxel products. To do this, they need to generate your <a href="/guide/affiliate-portal/generating-affiliate-links">affiliate link</a> from their affiliate dashboard.</p><p>You can copy this link and share it on their social media, blog, emails, or with their audience. When someone clicks on the link and purchases the product, the affiliate will earn a commission based on the rates you’ve configured.</p><h2 id="troubleshooting-common-issues" tabindex="-1">Troubleshooting Common Issues <a class="header-anchor" href="#troubleshooting-common-issues" aria-label="Permalink to &quot;Troubleshooting Common Issues&quot;">​</a></h2><p>If you run into any problems, here are a few common solutions:</p><ul><li><strong>Commissions Not Tracking:</strong> Double-check that the integration toggle is enabled in the settings. You can also place a test order using an affiliate link to ensure it&#39;s working correctly.</li></ul>',6))])}const _=a(u,[["render",g]]);export{b as __pageData,_ as default};
